import{_ as a,c as n,o,j as s,Y as r,t as i}from"./chunks/framework.BNTND4LZ.js";const u=JSON.parse('{"title":"hostname | x-cmd man (man7) | hostname resolution description","titleTemplate":false,"description":"x-cmd man (man7 Manual Page) | hostname - hostname resolution description","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"hostname | x-cmd man (man7) | hostname resolution description"}],["meta",{"name":"og:description","content":"x-cmd man (man7 Manual Page) | hostname - hostname resolution description"}]]},"headers":[],"params":{"isMan":true,"man":"hostname","category":"man7","desc":"hostname resolution description"},"relativePath":"man7/hostname.md","filePath":"man7/[man].md"}'),h={name:"man7/hostname.md"},m={class:"visually-hidden"};function l(t,e,d,c,p,f){return o(),n("div",null,[s("h1",m,i(t.$params.man),1),e[0]||(e[0]=r('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>hostname - hostname resolution description</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Hostnames are domains, where a domain is a hierarchical, dot-separated list of subdomains; for example, the machine &quot;monet&quot;, in the &quot;example&quot; subdomain of the &quot;com&quot; domain would be represented as &quot;monet.example.com&quot;.</p><p>Each element of the hostname must be from 1 to 63 characters long and the entire hostname, including the dots, can be at most 253 characters long. Valid characters for hostnames are <strong>ASCII</strong>(7) letters from <em>a</em> to <em>z</em>, the digits from <em>0</em> to <em>9</em>, and the hyphen (-). A hostname may not start with a hyphen.</p><p>Hostnames are often used with network client and server programs, which must generally translate the name to an address for use. (This task is generally performed by either <strong>getaddrinfo</strong>(3) or the obsolete <strong>gethostbyname</strong>(3).)</p><p>Hostnames are resolved by the NSS framework in glibc according to the <strong>hosts</strong> configuration in <strong>nsswitch.conf</strong>(5). The DNS-based name resolver (in the <strong>dns</strong> NSS service module) resolves them in the following fashion.</p><p>If the name consists of a single component, that is, contains no dot, and if the environment variable <strong>HOSTALIASES</strong> is set to the name of a file, that file is searched for any string matching the input hostname. The file should consist of lines made up of two white-space separated strings, the first of which is the hostname alias, and the second of which is the complete hostname to be substituted for that alias. If a case-insensitive match is found between the hostname to be resolved and the first field of a line in the file, the substituted name is looked up with no further processing.</p><p>If the input name ends with a trailing dot, the trailing dot is removed, and the remaining name is looked up with no further processing.</p><p>If the input name does not end with a trailing dot, it is looked up by searching through a list of domains until a match is found. The default search list includes first the local domain, then its parent domains with at least 2 name components (longest first). For example, in the domain cs.example.com, the name lithium.cchem will be checked first as lithium.cchem.cs.example and then as lithium.cchem.example.com. lithium.cchem.com will not be tried, as there is only one component remaining from the local domain. The search path can be changed from the default by a system-wide configuration file (see <strong>resolver</strong>(5)).</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>getaddrinfo</strong>(3), <strong>gethostbyname</strong>(3), <strong>nsswitch.conf</strong>(5), <strong>resolver</strong>(5), <strong>mailaddr</strong>(7), <strong>named</strong>(8)</p><p><a href="http://www.ietf.org/rfc/rfc1123.txt" target="_blank" rel="noreferrer">IETF RFC 1123</a></p><p><a href="http://www.ietf.org/rfc/rfc1178.txt" target="_blank" rel="noreferrer">IETF RFC 1178</a></p>',14))])}const b=a(h,[["render",l]]);export{u as __pageData,b as default};
